package com.enterprise.siem.server;
import com.enterprise.siem.database.EventRepository; import com.enterprise.siem.security.InputValidator; import com.enterprise.siem.security.TlsContextFactory; import com.enterprise.siem.security.TlsConfiguration; import com.enterprise.siem.util.*; import org.slf4j.*; import java.io.*; import java.net.*; import java.util.concurrent.*; import javax.net.ssl.SSLServerSocket;
public final class EnterpriseSIEMServer implements AutoCloseable { private static final Logger log=LoggerFactory.getLogger(EnterpriseSIEMServer.class); private static final int DEFAULT_MAX_CLIENTS=256; private static final int DEFAULT_MAX_EVENTS_PER_SECOND=1000; private static final int DEFAULT_QUEUE_CAPACITY=10_000; private final int port; private final InetAddress bindAddress; private final EventRepository events; private final com.enterprise.siem.detection.RuleEngine rules; private final SIEMMetrics metrics; private final ExecutorService workers=Executors.newVirtualThreadPerTaskExecutor(); private final ExecutorService processor=Executors.newSingleThreadExecutor(); private final BlockingQueue<PendingEvent> queue; private final Semaphore clients; private final int maxEventsPerSecond; private final int maxEventSizeBytes; private final TlsConfiguration tls; private volatile boolean running; private volatile Thread acceptThread; private ServerSocket server; private record PendingEvent(com.enterprise.siem.model.SecurityEvent event,String rawJson) {}
 public EnterpriseSIEMServer(int port,EventRepository events,com.enterprise.siem.detection.RuleEngine rules,SIEMMetrics metrics){this(port,events,rules,metrics,DEFAULT_MAX_CLIENTS,DEFAULT_MAX_EVENTS_PER_SECOND,InputValidator.MAX_EVENT_BYTES,TlsConfiguration.disabled(),DEFAULT_QUEUE_CAPACITY,InetAddress.getLoopbackAddress());}
 public EnterpriseSIEMServer(int port,EventRepository events,com.enterprise.siem.detection.RuleEngine rules,SIEMMetrics metrics,int maxClients){this(port,events,rules,metrics,maxClients,DEFAULT_MAX_EVENTS_PER_SECOND,InputValidator.MAX_EVENT_BYTES,TlsConfiguration.disabled(),DEFAULT_QUEUE_CAPACITY,InetAddress.getLoopbackAddress());}
 public EnterpriseSIEMServer(int port,EventRepository events,com.enterprise.siem.detection.RuleEngine rules,SIEMMetrics metrics,int maxClients,int maxEventsPerSecond,int maxEventSizeBytes,TlsConfiguration tls){this(port,events,rules,metrics,maxClients,maxEventsPerSecond,maxEventSizeBytes,tls,DEFAULT_QUEUE_CAPACITY,InetAddress.getLoopbackAddress());}
 public EnterpriseSIEMServer(int port,EventRepository events,com.enterprise.siem.detection.RuleEngine rules,SIEMMetrics metrics,int maxClients,int maxEventsPerSecond,int maxEventSizeBytes,TlsConfiguration tls,int queueCapacity){this(port,events,rules,metrics,maxClients,maxEventsPerSecond,maxEventSizeBytes,tls,queueCapacity,InetAddress.getLoopbackAddress());}
 public EnterpriseSIEMServer(int port,EventRepository events,com.enterprise.siem.detection.RuleEngine rules,SIEMMetrics metrics,int maxClients,int maxEventsPerSecond,int maxEventSizeBytes,TlsConfiguration tls,int queueCapacity,InetAddress bindAddress){if(port<0||port>65535)throw new IllegalArgumentException("port must be between 0 and 65535");if(maxClients<=0||maxEventsPerSecond<=0||maxEventSizeBytes<=0||queueCapacity<=0)throw new IllegalArgumentException("server limits must be positive");this.port=port;this.bindAddress=java.util.Objects.requireNonNull(bindAddress,"bindAddress");this.events=events;this.rules=rules;this.metrics=metrics;this.clients=new Semaphore(maxClients);this.maxEventsPerSecond=maxEventsPerSecond;this.maxEventSizeBytes=maxEventSizeBytes;this.tls=tls==null?TlsConfiguration.disabled():tls;if(!bindAddress.isLoopbackAddress()&&(!this.tls.enabled()||!this.tls.requireClientAuth()))throw new IllegalArgumentException("Non-loopback ingestion requires TLS and client certificate authentication");this.queue=new ArrayBlockingQueue<>(queueCapacity);}
 public void start() throws IOException {acceptThread=Thread.currentThread();running=true;processor.submit(this::processQueue);try{if(tls.enabled()){var factory=TlsContextFactory.create(tls).getServerSocketFactory();server=factory.createServerSocket(port,50,bindAddress);((SSLServerSocket)server).setNeedClientAuth(tls.requireClientAuth());}else server=new ServerSocket(port,50,bindAddress);server.setSoTimeout(1000);}catch(Exception exception){running=false;processor.shutdownNow();throw new IOException("Unable to initialize TLS server",exception);}if(!running)return;log.info("SIEM listening on {}:{}",bindAddress.getHostAddress(),port);while(running){try{Socket client=server.accept();if(!clients.tryAcquire()){metrics.eventsRejected.increment();client.close();continue;}metrics.activeConnections.incrementAndGet();workers.submit(()->handle(client));}catch(SocketTimeoutException ignored){}catch(IOException e){if(running)log.error("Accept failed",e);}}acceptThread=null;}
 public int boundPort(){return server==null?port:server.getLocalPort();}
 private void handle(Socket socket){long windowStart=System.nanoTime();int lines=0;try(socket;BoundedLineReader in=new BoundedLineReader(socket.getInputStream(),maxEventSizeBytes)){socket.setSoTimeout(10000);String line;while((line=in.readLine())!=null){if(System.nanoTime()-windowStart>=1_000_000_000L){windowStart=System.nanoTime();lines=0;}if(++lines>maxEventsPerSecond){metrics.eventsDropped.increment();metrics.eventsRejected.increment();log.warn("Rate limit exceeded for agent connection");break;}metrics.eventsReceived.increment();try{var event=InputValidator.parseStrict(line);validatePeerIdentity(socket,event);if(!queue.offer(new PendingEvent(event,line))){metrics.eventsDropped.increment();metrics.eventsRejected.increment();log.warn("Event queue full; event dropped");}else{metrics.eventsAccepted.increment();int size=queue.size();metrics.queueSize.set(size);metrics.queueHighWaterMark.accumulateAndGet(size,Math::max);}}catch(com.fasterxml.jackson.core.JsonProcessingException e){metrics.malformedEvents.increment();metrics.eventsRejected.increment();log.warn("Rejected malformed event: {}",e.getOriginalMessage());}catch(Exception e){metrics.eventsRejected.increment();log.warn("Rejected event: {}",e.getMessage());}}}catch(BoundedLineReader.LineTooLargeException e){metrics.oversizedEvents.increment();metrics.eventsDropped.increment();metrics.eventsRejected.increment();log.warn("Rejected oversized event");}catch(IOException e){log.debug("Agent disconnected: {}",e.getMessage());}finally{metrics.activeConnections.decrementAndGet();clients.release();}}
 private void validatePeerIdentity(Socket socket, com.enterprise.siem.model.SecurityEvent event) throws IOException {if(!tls.requireClientAuth())return;try{var ssl=(javax.net.ssl.SSLSocket)socket;var certificate=(java.security.cert.X509Certificate)ssl.getSession().getPeerCertificates()[0];String subject=certificate.getSubjectX500Principal().getName();String expected="CN="+event.agentId();if(java.util.Arrays.stream(subject.split(",")).noneMatch(part->part.trim().equalsIgnoreCase(expected)))throw new IOException("agent identity does not match client certificate");}catch(javax.net.ssl.SSLPeerUnverifiedException|ClassCastException exception){throw new IOException("client certificate identity unavailable",exception);}}
 private void processQueue(){while(running||!queue.isEmpty())try{PendingEvent item=queue.poll(250,TimeUnit.MILLISECONDS);if(item!=null){try{events.save(item.event(),item.rawJson());metrics.eventsPersisted.increment();rules.process(item.event());}catch(Exception e){metrics.processingErrors.increment();log.error("Event processing failed",e);}metrics.queueSize.set(queue.size());}}catch(InterruptedException e){Thread.currentThread().interrupt();return;}}
 public void close(){running=false;Thread thread=acceptThread;if(thread!=null){thread.interrupt();}try{if(server!=null)server.close();}catch(IOException ignored){}if(thread!=null&&thread!=Thread.currentThread())try{thread.join(2000);}catch(InterruptedException e){Thread.currentThread().interrupt();}workers.shutdown();try{if(!workers.awaitTermination(5,TimeUnit.SECONDS))workers.shutdownNow();}catch(InterruptedException e){workers.shutdownNow();Thread.currentThread().interrupt();}processor.shutdown();try{if(!processor.awaitTermination(5,TimeUnit.SECONDS))processor.shutdownNow();}catch(InterruptedException e){processor.shutdownNow();Thread.currentThread().interrupt();}}
}
